'use client'

import { motion } from 'framer-motion'
import { ChevronDown, Cookie, Database, Eye, Settings, Shield, Target } from 'lucide-react'
import { useState } from 'react'

export default function CookiePolicyPage() {
    const [openCategory, setOpenCategory] = useState('essential')
    const [cookiePreferences, setCookiePreferences] = useState({
        essential: true,
        analytics: false,
        marketing: false,
        personalization: false
    })

    const cookieCategories = [
        {
            id: 'essential',
            name: 'Essential Cookies',
            icon: <Shield className="text-green-400" size={20} />,
            description: 'Required for basic website functionality. Cannot be disabled.',
            examples: ['Authentication', 'Security', 'Session management'],
            purpose: 'Ensure website security and functionality',
            duration: 'Session'
        },
        {
            id: 'analytics',
            name: 'Analytics Cookies',
            icon: <Database className="text-blue-400" size={20} />,
            description: 'Help us understand how visitors interact with our website.',
            examples: ['Page visits', 'Time on site', 'Error tracking'],
            purpose: 'Improve website performance and user experience',
            duration: '2 years'
        },
        {
            id: 'marketing',
            name: 'Marketing Cookies',
            icon: <Target className="text-purple-400" size={20} />,
            description: 'Used to deliver relevant advertisements and track campaign performance.',
            examples: ['Ad targeting', 'Conversion tracking', 'Remarketing'],
            purpose: 'Measure marketing effectiveness',
            duration: '1 year'
        },
        {
            id: 'personalization',
            name: 'Personalization Cookies',
            icon: <Settings className="text-cyan-400" size={20} />,
            description: 'Remember your preferences and personalize your experience.',
            examples: ['Language settings', 'Theme preferences', 'Layout choices'],
            purpose: 'Enhance user experience',
            duration: '1 year'
        }
    ]

    const thirdPartyCookies = [
        {
            provider: 'Google Analytics',
            purpose: 'Website analytics',
            cookies: ['_ga', '_gid', '_gat'],
            privacy: 'https://policies.google.com/privacy'
        },
        {
            provider: 'Cloudflare',
            purpose: 'Security and performance',
            cookies: ['__cfduid', '__cf_bm'],
            privacy: 'https://www.cloudflare.com/privacypolicy/'
        },
        {
            provider: 'Microsoft Clarity',
            purpose: 'User behavior analytics',
            cookies: ['_clck', '_clsk'],
            privacy: 'https://clarity.microsoft.com/privacypolicy'
        }
    ]

    const handleCookieToggle = (category) => {
        if (category !== 'essential') {
            setCookiePreferences(prev => ({
                ...prev,
                [category]: !prev[category]
            }))
        }
    }

    const savePreferences = () => {
        localStorage.setItem('techodite-cookie-preferences', JSON.stringify(cookiePreferences))
        alert('Cookie preferences saved!')
    }

    const acceptAll = () => {
        const allAccepted = {
            essential: true,
            analytics: true,
            marketing: true,
            personalization: true
        }
        setCookiePreferences(allAccepted)
        localStorage.setItem('techodite-cookie-preferences', JSON.stringify(allAccepted))
        alert('All cookies accepted!')
    }

    const rejectAll = () => {
        const onlyEssential = {
            essential: true,
            analytics: false,
            marketing: false,
            personalization: false
        }
        setCookiePreferences(onlyEssential)
        localStorage.setItem('techodite-cookie-preferences', JSON.stringify(onlyEssential))
        alert('Non-essential cookies rejected!')
    }

    return (
        <div className="min-h-screen bg-gradient-to-br from-gray-900 to-black py-20">
            <div className="container mx-auto px-6 max-w-4xl">
                {/* Header */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="text-center mb-12"
                >
                    <div className="inline-flex items-center justify-center w-20 h-20 bg-gradient-to-r from-green-900/30 to-emerald-900/30 rounded-2xl mb-6">
                        <Cookie className="text-green-400" size={32} />
                    </div>
                    <h1 className="text-4xl md:text-5xl font-bold mb-4 bg-gradient-to-r from-green-400 to-emerald-400 bg-clip-text text-transparent">
                        Cookie Policy
                    </h1>
                    <p className="text-xl text-gray-300 mb-6">
                        How we use cookies to enhance your experience
                    </p>
                    <div className="inline-flex items-center px-4 py-2 bg-gray-800/50 rounded-full text-gray-400">
                        <span>Last Updated: February 1, 2024</span>
                    </div>
                </motion.div>

                {/* Introduction */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.1 }}
                    className="bg-gradient-to-br from-gray-800/30 to-gray-900/30 rounded-2xl border border-gray-700 p-8 mb-12"
                >
                    <h2 className="text-2xl font-bold text-white mb-6">What Are Cookies?</h2>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div className="space-y-4">
                            <p className="text-gray-300">
                                Cookies are small text files that are placed on your device when you visit our website.
                                They help us provide you with a better experience by:
                            </p>
                            <ul className="space-y-3 text-gray-300">
                                <li className="flex items-start">
                                    <span className="w-2 h-2 bg-green-500 rounded-full mr-3 mt-2 flex-shrink-0"></span>
                                    Remembering your preferences and settings
                                </li>
                                <li className="flex items-start">
                                    <span className="w-2 h-2 bg-green-500 rounded-full mr-3 mt-2 flex-shrink-0"></span>
                                    Understanding how you use our website
                                </li>
                                <li className="flex items-start">
                                    <span className="w-2 h-2 bg-green-500 rounded-full mr-3 mt-2 flex-shrink-0"></span>
                                    Keeping our website secure
                                </li>
                            </ul>
                        </div>
                        <div className="bg-gray-900/30 rounded-xl p-6 border border-gray-700">
                            <h3 className="text-lg font-bold text-white mb-4">Your Control</h3>
                            <p className="text-gray-300">
                                You have full control over cookies. You can manage your preferences at any time using
                                the controls below or through your browser settings.
                            </p>
                        </div>
                    </div>
                </motion.div>

                {/* Cookie Categories */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.2 }}
                    className="bg-gradient-to-br from-gray-800/30 to-gray-900/30 rounded-2xl border border-gray-700 p-8 mb-12"
                >
                    <h2 className="text-2xl font-bold text-white mb-8">Cookie Categories</h2>

                    <div className="space-y-4">
                        {cookieCategories.map((category) => (
                            <div key={category.id} className="border border-gray-700 rounded-xl overflow-hidden">
                                <button
                                    onClick={() => setOpenCategory(openCategory === category.id ? null : category.id)}
                                    className="w-full p-6 flex items-center justify-between bg-gray-900/30 hover:bg-gray-800/30 transition-colors"
                                >
                                    <div className="flex items-center gap-4">
                                        {category.icon}
                                        <div className="text-left">
                                            <h3 className="text-lg font-bold text-white">{category.name}</h3>
                                            <p className="text-sm text-gray-400">{category.description}</p>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-4">
                                        <div className="flex items-center gap-2">
                                            {category.id === 'essential' ? (
                                                <span className="px-3 py-1 bg-green-900/30 text-green-400 rounded-full text-sm">
                                                    Always Active
                                                </span>
                                            ) : (
                                                <label className="relative inline-flex items-center cursor-pointer">
                                                    <input
                                                        type="checkbox"
                                                        checked={cookiePreferences[category.id]}
                                                        onChange={() => handleCookieToggle(category.id)}
                                                        className="sr-only peer"
                                                    />
                                                    <div className="w-11 h-6 bg-gray-700 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-green-600"></div>
                                                </label>
                                            )}
                                        </div>
                                        <ChevronDown className={`text-gray-400 transition-transform ${openCategory === category.id ? 'rotate-180' : ''}`} />
                                    </div>
                                </button>

                                {openCategory === category.id && (
                                    <div className="p-6 bg-gray-900/20 border-t border-gray-700">
                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                            <div>
                                                <h4 className="text-sm font-semibold text-gray-400 mb-2">Purpose</h4>
                                                <p className="text-gray-300">{category.purpose}</p>
                                            </div>
                                            <div>
                                                <h4 className="text-sm font-semibold text-gray-400 mb-2">Duration</h4>
                                                <p className="text-gray-300">{category.duration}</p>
                                            </div>
                                        </div>
                                        <div className="mt-4">
                                            <h4 className="text-sm font-semibold text-gray-400 mb-2">Example Cookies</h4>
                                            <div className="flex flex-wrap gap-2">
                                                {category.examples.map((example, idx) => (
                                                    <span key={idx} className="px-3 py-1 bg-gray-800/50 text-gray-300 rounded-full text-sm">
                                                        {example}
                                                    </span>
                                                ))}
                                            </div>
                                        </div>
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                </motion.div>

                {/* Cookie Management */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.3 }}
                    className="bg-gradient-to-br from-gray-800/30 to-gray-900/30 rounded-2xl border border-gray-700 p-8 mb-12"
                >
                    <h2 className="text-2xl font-bold text-white mb-6">Manage Your Preferences</h2>

                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                        <button
                            onClick={acceptAll}
                            className="p-6 bg-gradient-to-r from-green-900/30 to-emerald-900/30 rounded-xl border border-green-800/30 hover:border-green-600 transition-all"
                        >
                            <div className="text-center">
                                <div className="w-12 h-12 bg-green-900/30 rounded-xl flex items-center justify-center mx-auto mb-4">
                                    <Cookie className="text-green-400" size={24} />
                                </div>
                                <h3 className="text-lg font-bold text-white mb-2">Accept All</h3>
                                <p className="text-gray-400 text-sm">Allow all cookies for best experience</p>
                            </div>
                        </button>

                        <button
                            onClick={savePreferences}
                            className="p-6 bg-gradient-to-r from-blue-900/30 to-cyan-900/30 rounded-xl border border-blue-800/30 hover:border-blue-600 transition-all"
                        >
                            <div className="text-center">
                                <div className="w-12 h-12 bg-blue-900/30 rounded-xl flex items-center justify-center mx-auto mb-4">
                                    <Settings className="text-blue-400" size={24} />
                                </div>
                                <h3 className="text-lg font-bold text-white mb-2">Save Preferences</h3>
                                <p className="text-gray-400 text-sm">Save current selection</p>
                            </div>
                        </button>

                        <button
                            onClick={rejectAll}
                            className="p-6 bg-gradient-to-r from-gray-900/30 to-gray-800/30 rounded-xl border border-gray-700 hover:border-gray-600 transition-all"
                        >
                            <div className="text-center">
                                <div className="w-12 h-12 bg-gray-800/30 rounded-xl flex items-center justify-center mx-auto mb-4">
                                    <Eye className="text-gray-400" size={24} />
                                </div>
                                <h3 className="text-lg font-bold text-white mb-2">Reject Non-Essential</h3>
                                <p className="text-gray-400 text-sm">Essential cookies only</p>
                            </div>
                        </button>
                    </div>

                    <div className="bg-gray-900/30 rounded-xl p-6 border border-gray-700">
                        <h3 className="text-lg font-bold text-white mb-4">Browser Controls</h3>
                        <p className="text-gray-300 mb-4">
                            You can also manage cookies through your browser settings. Here's how:
                        </p>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {[
                                { browser: 'Chrome', guide: 'Settings → Privacy and Security → Cookies' },
                                { browser: 'Firefox', guide: 'Options → Privacy & Security → Cookies' },
                                { browser: 'Safari', guide: 'Preferences → Privacy → Cookies' },
                                { browser: 'Edge', guide: 'Settings → Cookies and Site Permissions' }
                            ].map((item) => (
                                <div key={item.browser} className="p-4 bg-gray-800/30 rounded-lg">
                                    <p className="font-bold text-white mb-1">{item.browser}</p>
                                    <p className="text-sm text-gray-400">{item.guide}</p>
                                </div>
                            ))}
                        </div>
                    </div>
                </motion.div>

                {/* Third-Party Cookies */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.4 }}
                    className="bg-gradient-to-br from-gray-800/30 to-gray-900/30 rounded-2xl border border-gray-700 p-8 mb-12"
                >
                    <h2 className="text-2xl font-bold text-white mb-6">Third-Party Cookies</h2>

                    <div className="space-y-6">
                        {thirdPartyCookies.map((provider, idx) => (
                            <div key={idx} className="p-6 bg-gray-900/30 rounded-xl border border-gray-700">
                                <div className="flex items-center justify-between mb-4">
                                    <div>
                                        <h3 className="text-xl font-bold text-white mb-2">{provider.provider}</h3>
                                        <p className="text-gray-300">{provider.purpose}</p>
                                    </div>
                                    <a
                                        href={provider.privacy}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        className="px-4 py-2 border border-cyan-400 text-cyan-400 rounded-lg hover:bg-cyan-400/10 transition-colors whitespace-nowrap"
                                    >
                                        View Privacy Policy
                                    </a>
                                </div>

                                <div className="mb-4">
                                    <h4 className="text-sm font-semibold text-gray-400 mb-2">Cookies Used:</h4>
                                    <div className="flex flex-wrap gap-2">
                                        {provider.cookies.map((cookie, i) => (
                                            <span key={i} className="px-3 py-1 bg-gray-800/50 text-gray-300 rounded-full text-sm font-mono">
                                                {cookie}
                                            </span>
                                        ))}
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </motion.div>

                {/* Contact */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.5 }}
                    className="text-center"
                >
                    <div className="bg-gradient-to-r from-green-900/20 to-emerald-900/20 rounded-2xl p-8 border border-green-800/30">
                        <h2 className="text-2xl font-bold text-white mb-6">Questions About Cookies?</h2>
                        <p className="text-xl text-gray-300 max-w-2xl mx-auto mb-8">
                            Our Data Protection Officer is available to answer any questions about our cookie policy.
                        </p>
                        <a
                            href="mailto:dpo@techodite.com"
                            className="inline-block px-8 py-4 bg-gradient-to-r from-green-500 to-emerald-600 rounded-lg font-bold text-white hover:shadow-2xl hover:shadow-green-500/30 transition-all"
                        >
                            Contact DPO
                        </a>
                    </div>
                </motion.div>
            </div>
        </div>
    )
}